.dmm-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.dmm-root,.dmm-root *,.dmm-root *::before,.dmm-root *::after{box-sizing:border-box}
.dmm-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.dmm-root img{display:block;border:0;max-width:none}
.dmm-root > [data-node-id]{will-change:transform}
.dmm-root [hidden]{display:none!important}
.dmm-root [data-sh-theme="light"]{display:none!important}
.dmm-root[data-theme="light"] [data-sh-theme="light"]{display:block!important}
.dmm-root[data-theme="light"] [data-sh-theme="dark"]{display:none!important}
.dmm-root .n2921_1184{align-content:stretch;display:flex;flex-direction:column;gap:7px;align-items:center;position:relative;flex-shrink:0;width:61px;height:67px}
.dmm-root .n851_846{position:relative;flex-shrink:0;width:42px;height:42px}
.dmm-root .n851_847{position:absolute;inset:0;border-bottom-left-radius:4px;border-top-left-radius:4px;border-top-right-radius:4px;background-image:linear-gradient(-39.7680455014214deg, var(--wa-bg, rgb(0, 0, 0)) 50.648%, var(--wa-surface, rgb(31, 34, 38)) 50.648%)}
.dmm-root .n851_847::after{content:"";position:absolute;inset:-0px;border:1px solid var(--wa-line, #ccb7b7);border-radius:inherit;pointer-events:none}
.dmm-root .n851_848{position:absolute;display:contents;inset:0}
.dmm-root .n851_850{position:absolute;display:flex;inset:-47.22% -43.4% 64.52% 61.11%;align-items:center;justify-content:center;container-type:size}
